r:1px solid rgba(var(--theme-accent-rgb),.3);border-radius:4px;color:var(--theme-accent-strong);background:transparent;padding:10px 14px;font-size:12px}button:disabled{opacity:.4;cursor:default}.naming-preview{list-style:none;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:4px 20px}.naming-preview li{display:flex;justify-content:space-between;gap:12px;font-size:12px;border-bottom:1px solid rgba(var(--theme-accent-rgb),.15);padding:8px 0;margin:0}.naming-preview span{color:rgba(var(--theme-text-rgb),.6)}.naming-preview strong{font-weight:500}a{color:var(--theme-accent-strong)}a:focus-visible,summary:focus-visible,input:focus-visible,button:focus-visible{outline:2px solid var(--theme-accent-strong);outline-offset:3px}@media(max-width:760px){h2{font-size:29px}.reference-grid,.naming-vocab,.naming-preview{grid-template-columns:1fr}.naming-generator{padding:16px}.naming-output{font-size:30px}}
